"use strict";
import { useState } from "react";
import { useAccount } from "wagmi";
import { Contract } from "@ethersproject/contracts";
import { useEthersProvider } from "hooks/useEthersProvider";
import { getContractAddress, getContractAbi, ABSTRACT_TESTNET_CHAIN_ID } from "uniswap/src/constants/contracts";
import { UniverseChainId } from "uniswap/src/features/chains/types";
export function useClaimRewards() {
  const { address } = useAccount();
  const provider = useEthersProvider({ chainId: UniverseChainId.AbstractTestnet });
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState(null);
  const voterAddress = getContractAddress(ABSTRACT_TESTNET_CHAIN_ID, "Voter");
  const voterAbi = getContractAbi(ABSTRACT_TESTNET_CHAIN_ID, "Voter");
  const claimRewards = async (params) => {
    if (!address || !provider || !voterAddress || !voterAbi) {
      setError("Wallet not connected or contract not available");
      return { success: false };
    }
    const { tokenId, feeContracts, bribeContracts, feeTokens, bribeTokens } = params;
    setIsLoading(true);
    setError(null);
    try {
      console.log("\u{1F3AF} [CLAIM REWARDS] Starting claim process for tokenId:", tokenId);
      console.log("\u{1F3AF} [CLAIM REWARDS] Fee contracts:", feeContracts);
      console.log("\u{1F3AF} [CLAIM REWARDS] Bribe contracts:", bribeContracts);
      console.log("\u{1F3AF} [CLAIM REWARDS] Fee tokens:", feeTokens);
      console.log("\u{1F3AF} [CLAIM REWARDS] Bribe tokens:", bribeTokens);
      const signer = provider.getSigner();
      const voterContract = new Contract(voterAddress, voterAbi, signer);
      let transactionHash;
      if (bribeContracts.length > 0 && bribeTokens.length > 0) {
        console.log("\u{1F4B0} [CLAIM BRIBES] Preparing bribe claim transaction...");
        const bribesArray = bribeContracts;
        const tokensArray = bribeContracts.map(() => bribeTokens);
        console.log("\u{1F4B0} [CLAIM BRIBES] Calling claimBribes with:", {
          bribes: bribesArray,
          tokens: tokensArray,
          tokenId
        });
        const bribeTx = await voterContract.claimBribes(bribesArray, tokensArray, tokenId);
        console.log("\u{1F4B0} [CLAIM BRIBES] Transaction submitted:", bribeTx.hash);
        await bribeTx.wait();
        console.log("\u{1F4B0} [CLAIM BRIBES] Transaction confirmed");
        transactionHash = bribeTx.hash;
      }
      if (feeContracts.length > 0 && feeTokens.length > 0) {
        console.log("\u{1F4B0} [CLAIM FEES] Preparing fee claim transaction...");
        const feesArray = feeContracts;
        const tokensArray = feeContracts.map(() => feeTokens);
        console.log("\u{1F4B0} [CLAIM FEES] Calling claimFees with:", {
          fees: feesArray,
          tokens: tokensArray,
          tokenId
        });
        const feeTx = await voterContract.claimFees(feesArray, tokensArray, tokenId);
        console.log("\u{1F4B0} [CLAIM FEES] Transaction submitted:", feeTx.hash);
        await feeTx.wait();
        console.log("\u{1F4B0} [CLAIM FEES] Transaction confirmed");
        transactionHash = feeTx.hash;
      }
      console.log("\u2705 [CLAIM REWARDS] All claims completed successfully");
      setIsLoading(false);
      return { hash: transactionHash, success: true };
    } catch (err) {
      console.error("\u274C [CLAIM REWARDS] Error claiming rewards:", err);
      let errorMessage = "Failed to claim rewards";
      if (err?.message) {
        if (err.message.includes("user rejected")) {
          errorMessage = "Transaction was cancelled by user";
        } else if (err.message.includes("insufficient funds")) {
          errorMessage = "Insufficient funds for gas";
        } else if (err.message.includes("NotApprovedOrOwner")) {
          errorMessage = "You do not own this veABX lock";
        } else if (err.message.includes("execution reverted")) {
          errorMessage = "Transaction failed - please try again";
        } else {
          errorMessage = err.message;
        }
      }
      setError(errorMessage);
      setIsLoading(false);
      return { success: false };
    }
  };
  return {
    isLoading,
    error,
    claimRewards
  };
}
